import weakref

_spell: "weakref.WeakKeyDictionary[object, SpellState]" = weakref.WeakKeyDictionary()

def attach_spell(doc, state):            # side table, subject untouched
    _spell[doc] = state

def spell_check(doc, text):
    state = _spell.get(doc)              # absent capability -> None
    if state is None:
        return None
    return state.dictionary.check(text)
